+                status == LinkStatus.COMPLETED
+                        ? RegimeLink.dataInsufficientOrIncomplete(
+                                runId, command.caseRef(), command.scenario(), window, judged)
+                        : RegimeLink.pending(
+                                runId,
+                                command.caseRef(),
+                                command.scenario(),
